{
  "summary": "Added a location enum quality tracking where the crew currently is: street, lobby, or vault. It is extractor-sourced and read as a choice, since the prose will plainly state the crew's position.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "crew_location",
        "type": "enum",
        "source": "extractor",
        "values": ["street", "lobby", "vault"],
        "rubric": "Where is the crew right now? Answer street if they are outside the bank, lobby if they are inside the bank but not in the vault room, vault if they are inside the vault room.",
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Added a starter quality set for a blank format-2 story: a latching boolean for the protagonist's first irreversible commitment, a monotonic progress tracker, a tension rating, a location enum, and a code-driven chance roll for a random complication. These give the extractor something concrete to read from prose and give later checkpoints something to gate on. Adjust names/rubrics once the premise is known.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "committed",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "latching": true,
        "rubric": "Has the protagonist made an explicit, spoken commitment to the story's central course of action? true only when they say yes aloud or take an unmistakable binding action; false while they are still weighing options."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "progress",
        "type": "int",
        "source": "extractor",
        "read_as": "stated",
        "monotonic": true,
        "rubric": "On a 0-10 scale, how far has the protagonist advanced toward the story's immediate goal, based on concrete milestones reached in the prose? 0 = nothing done, 10 = goal achieved."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "enum",
        "source": "extractor",
        "read_as": "rating",
        "values": ["calm", "stirring", "tense", "critical", "peak"],
        "rubric": "What is the dramatic tension of the current scene? calm = ordinary conversation or rest; stirring = a hint of trouble or desire; tense = open conflict or stakes named; critical = violence, betrayal, or a decisive choice imminent; peak = the story's highest-stakes moment so far."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "location",
        "type": "enum",
        "source": "extractor",
        "read_as": "choice",
        "values": ["home", "road", "threshold", "elsewhere"],
        "rubric": "Where is the current scene set? home = the protagonist's familiar base; road = in transit between places; threshold = at the boundary of the story's central unknown; elsewhere = any other named place."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "complication",
        "type": "bool",
        "source": "code",
        "roll": { "sides": 6, "target": 2 },
        "rubric": "Seeded chance roll: true when a random complication interrupts the current beat."
      }
    }
  ]
}

{
  "summary": "Declared the dramatic-state qualities for the story: a latching boolean for the protagonist's commitment, a monotonic integer for progress toward the goal, a monotonic integer for trust with the key ally, a latching enum for which faction the protagonist has sided with, and a rated tension quality with an explicit 1-5 scale so the judge can score it every turn.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "committed",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "latching": true,
        "rubric": "Has the protagonist openly committed to the mission (spoken aloud or taken an irreversible action toward it)? true only when the prose shows the commitment; false while they are still weighing it."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "progress",
        "type": "int",
        "source": "extractor",
        "monotonic": true,
        "rubric": "How many of the story's major milestones toward the goal have been completed so far? Count only milestones the prose shows as finished, from 0 (none) upward."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "ally_trust",
        "type": "int",
        "source": "extractor",
        "monotonic": true,
        "rubric": "How much does the key ally trust the protagonist, from 0 (openly hostile or refusing to cooperate) to 5 (would risk their life for them)? Rate from the ally's words and actions in the prose."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "allegiance",
        "type": "enum",
        "source": "extractor",
        "read_as": "choice",
        "latching": true,
        "values": ["crown", "rebels", "neutral"],
        "rubric": "Which faction has the protagonist thrown in with? Answer 'crown' if they have sided with the crown, 'rebels' if with the rebels, 'neutral' if they have openly declared for neither."
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (calm, no threat in sight) to 5 (peak, immediate danger or open confrontation) — how tense is the current scene?",
        "criteria": {
          "levels": [
            { "value": 1, "label": "calm", "description": "No threat or conflict in the scene." },
            { "value": 2, "label": "stirring", "description": "Unease or friction, but nothing immediate." },
            { "value": 3, "label": "tense", "description": "Clear danger or conflict is present and unresolved." },
            { "value": 4, "label": "critical", "description": "Violence or betrayal is imminent or underway." },
            { "value": 5, "label": "peak", "description": "The scene's central confrontation is happening now." }
          ]
        }
      }
    }
  ]
}

{
  "summary": "Added an intermediate checkpoint 'The Lobby Door' between 'Casing the Bank' and 'The Vault', where the crew cracks the lobby door. It is wired into the existing flow: start -> lobby (always available) and lobby -> vault (gated on has_key, preserving the original condition). The original start -> vault transition is kept as a fallback so the vault remains reachable if the crew already has the key.",
  "ops": [
    {
      "kind": "addCheckpoint",
      "checkpoint": {
        "id": "lobby",
        "name": "The Lobby Door",
        "objective": "Crack the bank's lobby door and get the crew inside.",
        "type": "intermediate",
        "tension_target": "tense"
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "start",
        "to": "lobby",
        "priority": 1,
        "gate": { "q": "has_key", "op": "==", "v": false }
      }
    },
    {
      "kind": "addTransition",
      "transition": {
        "from": "lobby",
        "to": "vault",
        "priority": 1,
        "gate": { "q": "has_key", "op": "==", "v": true }
      }
    }
  ]
}

